// 제품 이미지에서 대표 컬러 4개 추출 (제품컷 배경 톤 하모니)
function extractPalette(src) {
  return new Promise(resolve => {
    const img = new Image();
    img.onload = () => {
      try {
        const c = document.createElement('canvas'), x = c.getContext('2d');
        c.width = 80; c.height = 80; x.drawImage(img, 0, 0, 80, 80);
        const d = x.getImageData(0, 0, 80, 80).data, bins = {};
        for (let i = 0; i < d.length; i += 16) {
          if (d[i + 3] < 180) continue;
          const r = Math.round(d[i] / 32) * 32, g = Math.round(d[i + 1] / 32) * 32, b = Math.round(d[i + 2] / 32) * 32;
          if (Math.max(r, g, b) > 245 && Math.min(r, g, b) > 245) continue; // 순백 배경 제외
          const k = `${r},${g},${b}`; bins[k] = (bins[k] || 0) + 1;
        }
        let colors = Object.entries(bins).sort((a, b) => b[1] - a[1]).slice(0, 4).map(([k]) => {
          const [r, g, b] = k.split(',').map(Number);
          return '#' + [r, g, b].map(v => Math.min(255, v).toString(16).padStart(2, '0')).join('');
        });
        if (colors.length < 4) colors = [...colors, '#f1eee8', '#d8d0c4', '#b7ada0', '#ffffff'].slice(0, 4);
        resolve(colors);
      } catch (e) { resolve(['#e9e7e2', '#c8c1b6', '#9b958c', '#f8f7f4']); }
    };
    img.onerror = () => resolve(['#e9e7e2', '#c8c1b6', '#9b958c', '#f8f7f4']);
    img.src = src;
  });
}

/* ---------- 저장/불러오기 ---------- */
function loadModels() {
  try {
    const s = JSON.parse(localStorage.getItem(LS_MODELS) || 'null');
    if (Array.isArray(s) && s.length) return s;
  } catch (e) {}
  return JSON.parse(JSON.stringify(DEFAULT_MODELS));
}
function saveModels() { localStorage.setItem(LS_MODELS, JSON.stringify(state.models)); }

/* ---------- 유틸 ---------- */
const $ = sel => document.querySelector(sel);
const $$ = sel => Array.from(document.querySelectorAll(sel));

function toast(msg) {
  const t = $('#toast');
  t.textContent = msg;
  t.classList.add('show');
  clearTimeout(toast._t);
  toast._t = setTimeout(() => t.classList.remove('show'), 2600);
}

function fileToDataURL(file) {
  return new Promise((resolve, reject) => {
    const r = new FileReader();
    r.onload = () => resolve(r.result);
    r.onerror = reject;
    r.readAsDataURL(file);
  });
}

// 이미지 리사이즈(용량/속도) — 최대 1280px, jpeg 0.88
function shrinkImage(dataUrl, max = 1280) {
  return new Promise(resolve => {
    const im = new Image();
    im.onload = () => {
      let { width: w, height: h } = im;
      if (Math.max(w, h) > max) {
        const r = max / Math.max(w, h);
        w = Math.round(w * r); h = Math.round(h * r);
      }
      const cv = document.createElement('canvas');
      cv.width = w; cv.height = h;
      cv.getContext('2d').drawImage(im, 0, 0, w, h);
      resolve(cv.toDataURL('image/jpeg', 0.88));
    };
    im.onerror = () => resolve(dataUrl);
    im.src = dataUrl;
  });
}

// URL/경로 이미지를 dataURL로 변환(같은 출처 또는 CORS 허용 시). 실패하면 null.
function ensureDataUrl(src) {
  return new Promise(resolve => {
    if (!src) return resolve(null);
    if (src.startsWith('data:')) return resolve(src);
    const im = new Image();
    im.crossOrigin = 'anonymous';
    im.onload = () => {
      try {
        const cv = document.createElement('canvas');
        cv.width = im.naturalWidth; cv.height = im.naturalHeight;
        cv.getContext('2d').drawImage(im, 0, 0);
        resolve(cv.toDataURL('image/jpeg', 0.9));
      } catch (e) { resolve(null); }
    };
    im.onerror = () => resolve(null);
    im.src = src;
  });
}

async function ingestFiles(files, onEach) {
  const imgs = Array.from(files).filter(f => f.type.startsWith('image/'));
  if (!imgs.length) { toast('이미지 파일만 올릴 수 있어요'); return; }
  for (const f of imgs) {
    if (f.size > 15 * 1024 * 1024) { toast(`${f.name}: 15MB를 넘습니다`); continue; }
    const raw = await fileToDataURL(f);
    const small = await shrinkImage(raw);
    onEach(small);
  }
}

function download(url, filename) {
  const a = document.createElement('a');
  a.href = url; a.download = filename;
  document.body.appendChild(a); a.click(); a.remove();
}

