const ANGLE_SETS = { clothing: CLOTHING_ANGLES, beauty: BEAUTY_ANGLES, product: PRODUCT_ANGLES };
const CONCEPT_MODES = ['beauty', 'product']; // 컨셉 개별 선택 모드

function buildPhotoPrompt(model, angle, userExtra, productType) {
  const extra = userExtra ? `Extra direction: ${userExtra}` : '';

  // ===== 제품 단독 화장품 연출컷 (모델 없음) =====
  if (productType === 'product') {
    const gv = id => { const e = document.getElementById(id); return e ? e.value : ''; };
    const an = state.analysis || null;
    // AI 분석값을 우선 사용하고, 없으면 수동 셀렉트값
    const type = (an && an.category) || gv('prodCat') || '스킨케어 제품';
    const texture = (an && an.texture) || gv('prodTexture') || '부드러운 크림 제형';
    const mood = (an && an.mood) || gv('prodMood') || '미니멀 프리미엄';
    const dpal = ['#e9e7e2', '#c8c1b6', '#9b958c', '#f8f7f4', '#efe7e0'];
    const pal = (an && an.palette && an.palette.length >= 5) ? an.palette
      : (state.palette && state.palette.length >= 4) ? [...state.palette, state.palette[0]]
        : dpal;
    const base = pal[0], light = pal[1], deep = pal[2], warm = pal[3], cool = pal[4] || pal[0];

    const identity = `CRITICAL PRODUCT IDENTITY LOCK: Use the uploaded product as the only product reference. Preserve its exact bottle/tube/jar shape, proportions, cap or pump structure, label layout, typography, logo, packaging color, transparency, reflections, and material. Do not redesign, simplify, invent, replace, duplicate incorrectly, or add text. The product must look like a real commercial photograph, not a 3D render.`;

    // 브랜드 톤앤매너 (AI 분석 결과를 프롬프트로 주입 → 톤에 맞는 이미지)
    const brand = an ? [
      an.productName ? `Product name: ${an.productName}.` : '',
      an.size ? `Real-world product size: ${an.size}. Keep the product's true physical scale and proportions accurate — when a hand, table or other object appears in frame, size the product realistically against it so it is never enlarged or shrunk.` : '',
      an.features ? `Key selling points to convey visually: ${an.features}.` : '',
      an.toneSummary ? `Brand tone & manner to follow: ${an.toneSummary}` : '',
      (an.bottleShape || an.material) ? `The real product is a ${an.bottleShape || ''}${an.material ? `, made of ${an.material}` : ''} — reproduce it faithfully.` : '',
      an.labelPosition ? `Label layout: ${an.labelPosition}. Keep the label crisp and readable.` : '',
      an.lighting ? `Preferred lighting: ${an.lighting}` : '',
      (an.productColor || an.secondaryColor) ? `Keep the product's signature colors consistent (primary ${an.productColor || ''}${an.secondaryColor ? `, accent ${an.secondaryColor}` : ''}) and harmonize the whole scene with this palette.` : '',
    ].filter(Boolean).join(' ') : '';

    const shot = (angle.tpl || '')
      .split('[PRODUCT_TYPE]').join(type)
      .split('[TEXTURE]').join(texture)
      .split('[BASE_PALETTE]').join(`${base} and tonal variations`)
      .split('[LIGHT_PALETTE]').join(`${light} and softer pastel variations`)
      .split('[DEEP_PALETTE]').join(`${deep} and richer tonal variations`)
      .split('[WARM_PALETTE]').join(`${warm} and warm tonal variations`)
      .split('[COOL_PALETTE]').join(`${cool} and cool watery tonal variations`);

    const rules = `Composition rules: single finished advertising image, no collage, no split screen, no watermark, no random lettering, no extra products unless the shot explicitly requests a dual product.` +
      (angle.hand ? ' Render the hand with correct natural anatomy — exactly one hand with five fingers, no extra or malformed hands.' : '');

    return [
      identity,
      brand,
      `Product category: ${type}. Formula/texture: ${texture}. Brand mood: ${mood}.`,
      shot,
      rules,
      extra ? `Additional request: ${userExtra}` : '',
    ].filter(Boolean).join('\n');
  }

  // ===== 뷰티 제품 =====
  if (productType === 'beauty') {
    const noFace = !!angle.detail; // 손+제품 / 텍스처 / 히어로 = 얼굴 없음
    const who = noFace
      ? ''
      : (model
          ? `Feature ${model.name}${model.desc ? ', ' + model.desc : ''}; use the provided reference photo and keep the exact same face and skin.`
          : 'A professional beauty model.');
    const handSafe = angle.hand
      ? `Render hands with correct natural human anatomy: show only the hand(s) described, exactly five fingers each, no extra, duplicated, merged or malformed hands or fingers.`
      : '';
    return [
      who,
      `High-end beauty product advertising photo. Use the uploaded product exactly as shown — keep its packaging, label text, colors and shape faithful.`,
      `Shot: ${angle.en}.`,
      noFace ? `Do NOT show any face; keep the product the clear hero of the frame.` : '',
      handSafe,
      `Clean studio background, soft flattering beauty lighting, realistic advertising photography, high detail, vertical 3:4.`,
      extra,
    ].filter(Boolean).join(' ');
  }

  // ===== 의류 =====
  // 디테일 컷: 얼굴 없이 옷에만 집중
  if (angle.detail) {
    return [
      `Extreme close-up macro shot of the outfit worn on the body: ${angle.en}.`,
      `Focus entirely on the clothing — show fabric weave, buttons, stitching, zipper and logo in sharp detail.`,
      `Do NOT show the model's face or head; crop tightly to the garment so no face is visible.`,
      `Soft even studio lighting, photorealistic, high detail, vertical 3:4.`,
      extra,
    ].filter(Boolean).join(' ');
  }
  const who = model
    ? `Use the provided reference photo as the model (${model.name}${model.desc ? ', ' + model.desc : ''}). Keep the same face and body.`
    : `A professional fashion model.`;
  return [
    who,
    `Dress the model in the uploaded clothing item exactly as shown (keep colors, print, logo and details faithful).`,
    `Shot: ${angle.en}.`,
    `Clean studio background, realistic fashion catalog photography, high detail, vertical 3:4.`,
    extra,
  ].filter(Boolean).join(' ');
}

// 모델 참조 이미지/메타 준비 (사진·영상 공용)
async function resolveModel() {
  const model = selectedModel();
  const usesModel = state.productType !== 'product';
  const modelImg = (usesModel && model) ? (await ensureDataUrl(model.photo)) || model.photo || null : null;
  const modelMeta = (usesModel && model) ? { id: model.id, name: model.name, desc: model.desc } : null;
  return { model, modelImg, modelMeta };
}

// 선택한 출력(사진/영상)을 한 번에 생성
async function generate() {
  const wantVideo = $('#outVideo').checked;
  const wantPhoto = $('#outPhoto').checked;
  if (!state.products.length) { toast('사진/제품 이미지를 먼저 올려주세요'); return; }
  if (!wantVideo && !wantPhoto) { toast('영상·사진 중 하나 이상 선택하세요'); return; }

  const btn = $('#btnGenerate'); if (btn.disabled) return;
  const lbl = btn.textContent; btn.disabled = true;

  $('#results').hidden = false;
  $('#results').scrollIntoView({ behavior: 'smooth', block: 'start' });
  const { model, modelImg, modelMeta } = await resolveModel();

  try {
    /* ----- 사진 (제미나이) ----- */
    if (wantPhoto) {
      const set = ANGLE_SETS[state.productType] || CLOTHING_ANGLES;
      let angles;
      if (CONCEPT_MODES.includes(state.productType)) {
        angles = set.filter(a => state.concepts.has(a.pose));
      } else {
        angles = set.slice(0, parseInt($('#photoCount').value, 10));
      }
      if (!angles.length) {
        toast('컨셉을 하나 이상 선택하세요');
      } else {
        $('#resultPhotos').hidden = false;
        const userExtra = $('#photoPrompt').value.trim();
        const gal = $('#photoGallery'); gal.innerHTML = '';
        angles.forEach((a, i) => {
          const it = document.createElement('div');
          it.className = 'pg-item'; it.id = `pg-${i}`;
          it.innerHTML = `<div class="pg-loading"><span class="spin"></span></div><div class="pg-cap"><span>${a.key}</span></div>`;
          gal.appendChild(it);
        });
        btn.textContent = '🖼️ 사진 생성 중…';
        for (let i = 0; i < angles.length; i++) {
          const a = angles[i];
          const prompt = buildPhotoPrompt(model, a, userExtra, state.productType);
          try {
            const img = await StudioAPI.geminiPhoto(prompt, modelImg, state.products,
              { pose: a.pose, angleLabel: a.key, model: modelMeta,
                beauty: state.productType === 'beauty', productOnly: state.productType === 'product' });
            const slot = $(`#pg-${i}`);
            slot.innerHTML = `<img src="${img}" alt="${a.key}"><div class="pg-cap"><span>${a.key}</span><a class="pg-dl" href="#">저장 ↓</a></div>`;
            slot.querySelector('.pg-dl').onclick = e => { e.preventDefault(); download(img, `연출_${a.key}_${i + 1}.png`); };
          } catch (err) {
            $(`#pg-${i}`).innerHTML = `<div class="pg-loading" style="color:var(--red);font-size:11px;padding:10px;text-align:center">${a.key}<br>실패: ${escapeHtml(err.message)}</div>`;
          }
        }
      }
    } else { $('#resultPhotos').hidden = true; }

    /* ----- 영상 ----- */
    if (wantVideo) {
      $('#resultVideo').hidden = false;
      const wrap = $('#rvWrap');
      wrap.innerHTML = `<div class="rv-placeholder" style="display:flex;align-items:center;justify-content:center;color:var(--ink3);font-size:12px;flex-direction:column;gap:10px"><span class="spin"></span>영상 생성 중…</div>`;
      btn.textContent = '🎬 영상 생성 중…';
      const vprompt = $('#videoPrompt').value.trim() || videoPromptFor(state.productType);
      try {
        const out = await StudioAPI.grokVideo(vprompt, state.products, { duration: 10, aspect: '9:16', modelImage: modelImg, model: modelMeta });
        const ext = out.mime && out.mime.includes('webm') ? 'webm' : 'mp4';
        wrap.innerHTML = `<video src="${out.url}" controls autoplay muted loop playsinline></video>
          <div class="rv-dl"><a class="dlbtn" id="vdl">⬇ 영상 저장 (.${ext})</a>
          ${out.demo ? '<div class="tiny" style="margin-top:6px">DEMO 영상입니다. 실제 영상 API 연결 시 실사가 생성됩니다.</div>' : ''}</div>`;
        $('#vdl').onclick = () => download(out.url, `비주얼메이커_영상.${ext}`);
      } catch (err) {
        wrap.innerHTML = `<div class="rv-placeholder" style="display:flex;align-items:center;justify-content:center;color:var(--red);font-size:12px;padding:16px;text-align:center">영상 생성 실패<br>${escapeHtml(err.message)}</div>`;
      }
    } else { $('#resultVideo').hidden = true; }

    toast('완료되었습니다 🎉');
  } finally { btn.disabled = false; btn.textContent = lbl; }
}

/* ============================================================
   설정 모달
   ============================================================ */
function openSettings() {
  const s = StudioAPI.getSettings();
  $('#setGeminiKey').value = s.geminiKey;
  $('#setGeminiModel').value = s.geminiModel;
  $('#setGrokUrl').value = s.grokUrl;
  $('#setGrokKey').value = s.grokKey;
  $('#setGrokModel').value = s.grokModel;
  $('#setStatus').textContent = '';
  $('#settingsModal').classList.add('open');
}
function saveSettingsUI() {
  StudioAPI.saveSettings({
    geminiKey: $('#setGeminiKey').value.trim(),
    geminiModel: $('#setGeminiModel').value.trim() || 'gemini-2.5-flash-image',
    grokUrl: $('#setGrokUrl').value.trim(),
    grokKey: $('#setGrokKey').value.trim(),
    grokModel: $('#setGrokModel').value.trim() || 'grok-video',
  });
  updateConnBanner();
  toast('저장되었습니다');
  $('#settingsModal').classList.remove('open');
}
async function testConn() {
  const st = $('#setStatus');
  const key = $('#setGeminiKey').value.trim();
  if (!key) { st.className = 'set-status err'; st.textContent = '제미나이 키를 입력하면 연결을 확인합니다.'; return; }
  st.className = 'set-status'; st.textContent = '확인 중…';
  try {
    const res = await fetch(`https://generativelanguage.googleapis.com/v1beta/models?key=${encodeURIComponent(key)}`);
    if (res.ok) { st.className = 'set-status ok'; st.textContent = '✓ 제미나이 키 정상'; }
    else { st.className = 'set-status err'; st.textContent = `✗ 제미나이 응답 ${res.status}`; }
  } catch (e) {
    st.className = 'set-status err'; st.textContent = '✗ 네트워크 오류: ' + e.message;
  }
}

/* ============================================================
   초기화
   ============================================================ */
async function init() {
  state.models = loadModels();
  state.selectedModelId = state.models[0]?.id || null;
  renderModels();
  renderThumbs();
  $('#videoPrompt').value = videoPromptFor(state.productType);
  setupDropzone();
  setupPaste();
  updateConnBanner();
  updateGenInfo();
  // 백엔드 서버 연결 확인 후 배너 갱신
  StudioAPI.init().then(updateConnBanner);

  // 상단 버튼
  $('#btnAdmin').onclick = openAdmin;
  $('#btnAddModelInline').onclick = openAdmin;
  $('#btnSettings').onclick = openSettings;
  $('#btnGenerate').onclick = generate;
  $('#btnResetPrompt').onclick = () => { $('#videoPrompt').value = videoPromptFor(state.productType); toast('기본 프롬프트로 되돌렸어요'); };
  $('#btnClearResults').onclick = () => { $('#results').hidden = true; };

  // 장수 변경 → 정보 갱신
  $('#photoCount').addEventListener('change', updateGenInfo);

  // 제품 종류 토글 (의류/뷰티/제품컷)
  $$('#ptypeSeg .seg-btn').forEach(b => b.onclick = () => setProductType(b.dataset.pt));
  // 컨셉 전체/해제
  $('#conceptAll').onclick = () => { state.concepts = new Set((ANGLE_SETS[state.productType] || []).map(a => a.pose)); renderConceptChips(); updateGenInfo(); };
  $('#conceptNone').onclick = () => { state.concepts.clear(); renderConceptChips(); updateGenInfo(); };

  // 제품 AI 분석 다시 실행
  const bAnal = $('#btnAnalyze'); if (bAnal) bAnal.onclick = () => { state.analysis = null; runAnalysis(); };
  // 분석값 수기 수정 → state.analysis 반영 (생성에 그대로 사용)
  const aBody = $('#aiAnalysisBody');
  if (aBody) aBody.addEventListener('input', e => {
    const el = e.target.closest('[data-af]');
    if (el && state.analysis) state.analysis[el.dataset.af] = el.value;
  });

  // 모델 폼
  $('#modelForm').onsubmit = submitModelForm;
  $('#mfReset').onclick = resetModelForm;
  $('#mfPhotoBtn').onclick = () => $('#mfPhotoInput').click();
  $('#mfPhotoInput').onchange = e => { ingestFiles(e.target.files, setModelPhoto); e.target.value = ''; };
  // 모델 사진 미리보기 영역 드래그
  const prev = $('#mfPhotoPrev');
  prev.addEventListener('dragover', e => { e.preventDefault(); });
  prev.addEventListener('drop', e => { e.preventDefault(); if (e.dataTransfer.files.length) ingestFiles(e.dataTransfer.files, setModelPhoto); });

  // 설정
  $('#btnSaveSettings').onclick = saveSettingsUI;
  $('#btnTestConn').onclick = testConn;

  // 모달 닫기
  $$('[data-close]').forEach(b => b.onclick = () => $('#' + b.dataset.close).classList.remove('open'));
  $$('.modal-ov').forEach(ov => ov.addEventListener('click', e => { if (e.target === ov) ov.classList.remove('open'); }));
  window.addEventListener('keydown', e => { if (e.key === 'Escape') $$('.modal-ov.open').forEach(m => m.classList.remove('open')); });
}

document.addEventListener('DOMContentLoaded', init);
